import {jest} from '@jest/globals';
import {InMemorySessionStore} from './inMemorySessionStore.js';
import type {SessionCursor} from '../../types/sessionStore.js';

// A list and the latest session read the same activity, so the two can never disagree about which is newest.

const START = new Date('2026-01-01T00:00:00.000Z');
const later = (ms: number): Date => new Date(START.getTime() + ms);

const refusalOf = (call: () => unknown): string => {
  try {
    call();
    return 'no refusal';
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
};

describe('the in-memory store conversation list', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(START);
  });

  afterEach(() => jest.useRealTimers());

  it('answers newest activity first, headed by the very session latestFor returns', () => {
    const store = new InMemorySessionStore();
    store.create('older', 'u1');
    jest.setSystemTime(later(1000));
    const talkedIn = store.create('newer', 'u1');
    talkedIn.entries.push({role: 'user', content: 'hello', timestamp: later(5000).toISOString()});

    const listed = store.listFor('u1');

    expect({
      order: listed.map(row => row.sessionId),
      heads: listed[0]?.sessionId === store.latestFor('u1')?.sessionId,
    }).toEqual({order: ['newer', 'older'], heads: true});
  });
  orchestrator: ChatOrchestrator = answeringOrchestrator
) => {
  const auth = {userId: 'u1'};
  const connects: Array<{sessionId: string; resumed: boolean}> = [];
  const disconnected: string[] = [];
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore: store,
    orchestrator,
    resume,
    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
    onDisconnect: sessionId => void disconnected.push(sessionId),
  });
  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
  const firstServerClose = new Promise<void>(resolve => {
    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
};

// One question answered and the socket closed, returning the id the connected frame announced.
const firstTurn = async (base: string): Promise<string> => {
  const client = open(base);
  let sessionId = '';
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
      if (frame.type === 'stream_end') resolve();
    });
  });
  client.close();
  await once(client, 'close');
  return sessionId;
};

// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
  const client = open(url, token);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
};
import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}

