    };
    const {url} = await startEngineWith({sessionStore: new RecordingStore(), orchestrator: slowAnswer, ...{history: HISTORY_ON}});
    const client = connectClient(url);
    const order: string[] = [];
    const ended = new Promise<void>(resolve => {
      client.on('message', raw => {
        const {type} = JSON.parse(String(raw)) as Frame;
        if (type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'take your time'}));
        if (type === 'conversation_list' || type === 'stream_end' || type === 'error') order.push(type);
