    const grace = setTimeout(() => hold.release(), 2000);
    await ended;
    clearTimeout(grace);

    expect(order).toEqual(['conversation_list', 'stream_end']);
  });
});

describe('the list_conversations frame validator', () => {
  it('accepts a bare list_conversations and refuses a limit or cursor it cannot page on, naming the field', () => {
    const refusal = (frame: Record<string, unknown>): string => {
      const result = validateMessage({type: 'list_conversations', ...frame});
      return result.valid ? 'accepted' : result.error;
    };

    expect({
      bare: validateMessage({type: 'list_conversations'}).valid,
      limitZero: refusal({limit: 0}),
      limitOver: refusal({limit: 201}),
      limitFraction: refusal({limit: 1.5}),
      limitString: refusal({limit: '10'}),
      beforeNotADate: refusal({before: 'not a date'}),
      beforeBadTime: refusal({before: {updatedAt: 'not a date', sessionId: 's1'}}),
      beforeHalf: refusal({before: {updatedAt: '2026-01-03T10:00:00.000Z'}}),
    }).toEqual({
      bare: true,
      limitZero: expect.stringContaining('limit'),
      limitOver: expect.stringContaining('limit'),
      limitFraction: expect.stringContaining('limit'),
      limitString: expect.stringContaining('limit'),
      beforeNotADate: expect.stringContaining('before'),
